Исходный алгоритм каждый раз линейно ищет значение в результате и может занять O(n²). unordered_set даёт среднее O(1) для проверки принадлежности; вектор сохраняет исходный порядок.

```cpp
#include <unordered_set>
#include <vector>

std::vector<int> uniqueValues(const std::vector<int>& values) {
    std::unordered_set<int> seen;
    std::vector<int> result;
    result.reserve(values.size());
    for (int value : values) {
        if (seen.insert(value).second) {
            result.push_back(value);
        }
    }
    return result;
}
