```rust
pub fn parse_limit(input: &str) -> Result<usize, String> {
    let value = input
        .trim()
        .parse::<usize>()
        .map_err(|_| String::from("limit must be a positive integer"))?;
    if value == 0 {
        return Err(String::from("limit must be greater than zero"));
    }
    Ok(value)
}
```
